-- ============================================================
-- 桂離宮とブルーノ・タウト（テーマID: 18, category_id: 5）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(5, 18, '桂離宮を最初に造営した皇族はだれか。', '後水尾天皇', '後陽成天皇', '八条宮智仁親王', '後嵯峨天皇', 2, '桂離宮は江戸時代初期の1616年頃から、八条宮智仁親王（はちじょうのみやとしひとしんのう）が造営を始めました。桂川のほとりに設けた別荘が起源で、智仁親王・智忠親王（2代）によって現在の規模に整えられました。', 1, false),
(5, 18, '桂離宮を「日本建築の最高峰」として世界に紹介したドイツ人建築家はだれか。', 'フランク・ロイド・ライト', 'ル・コルビュジエ', 'ブルーノ・タウト', 'ヴァルター・グロピウス', 2, 'ブルーノ・タウト（Bruno Taut、1880〜1938年）はドイツの建築家で、1933年に来日し桂離宮を訪問して「涙が出るほど美しい」と激賞しました。桂離宮の美を世界に紹介し、国際的な評価を高めた人物です。', 1, false),
(5, 18, '桂離宮がある場所（行政区）として正しいのはどれか。', '右京区嵯峨', '西京区桂', '伏見区桂', '南区桂', 1, '桂離宮は京都市西京区桂（かつら）に位置します。桂川の西岸に広がる敷地に、書院・庭園・茶屋などが配置されています。宮内庁が管理しており、事前申し込みが必要です。', 1, false),
(5, 18, '桂離宮の庭園様式として正しいのはどれか。', '枯山水式庭園', '池泉回遊式庭園', '露地式庭園', '坪庭式庭園', 1, '桂離宮の庭園は「池泉回遊式庭園」です。松琴亭・笑意軒・賞花亭・月波楼など複数の茶屋が配置されており、池の周囲を歩きながら各所で異なる景観が楽しめる回遊式です。', 1, false),
(5, 18, 'ブルーノ・タウトが桂離宮を絶賛する一方で、同時代の「日光東照宮」について述べたこととして知られるのはどれか。', '日光東照宮も同様に美しい傑作と評価した', '日光東照宮は装飾過多で桂離宮の対極にあると批判した', '日光東照宮は技術的に桂離宮より優れていると評価した', '日光東照宮については言及しなかった', 1, 'タウトは桂離宮の余白の美・簡素さを絶賛する一方で、日光東照宮の過剰な装飾を「装飾の過多」「成り上がり者の趣味」と批判しました。この対比が日本建築論議に大きな影響を与えました。', 2, false),
(5, 18, '桂離宮の代表的な茶屋「松琴亭（しょうきんてい）」の名前の由来はどれか。', '松の木と琴の音に由来', '古今和歌集の歌「松琴」から', '松の葉が琴の弦に似るため', '建築した職人の名前から', 1, '松琴亭の名は「古今和歌集」の和歌「松風・松琴」（松の木の風が琴の音のように聞こえる）から取られています。桂離宮で最大の茶屋で、青と白の市松模様の障子が有名です。', 2, false),
(5, 18, '桂離宮の市松模様（青白）で知られる障子がある建物はどれか。', '笑意軒', '松琴亭', '賞花亭', '月波楼', 1, '松琴亭（しょうきんてい）の一の間には、青と白の市松模様の障子があり、桂離宮を代表するデザインとして広く知られています。この大胆な幾何学的パターンが近代建築にも通じると評価されました。', 1, false),
(5, 18, '桂離宮の庭園に面した「月見台」が設けられている建物はどれか。', '松琴亭', '笑意軒', '古書院', '月波楼', 2, '桂離宮の古書院（こしょいん）南側には月見台（つきみだい）が設けられており、池に映る月を楽しむためのスペースです。竹縁（たけえん）が設けられた月見台は「月の名所」として有名です。', 2, false),
(5, 18, '桂離宮の造営にあたり、智仁親王が影響を受けたとされる文学・文化はどれか。', '源氏物語', '万葉集', '古今和歌集の歌枕「桂」に由来する王朝文化', '平家物語', 2, '桂（かつら）は古今和歌集などに詠まれた歌枕のひとつで、月・詩情・風流と結び付けられた地名です。智仁親王はこの王朝文化への敬愛から桂の地に別荘を構え、月を愛でる庭園として設計したとされています。', 3, false),
(5, 18, '桂離宮を参観するために必要なことはどれか。', '特に予約は必要なく入場できる', '宮内庁への事前申込みが必要', '文化庁への申請が必要', '京都府教育委員会への申請が必要', 1, '桂離宮は宮内庁が管理する皇室用財産であり、参観には宮内庁への事前申込みが必要です。オンライン・往復はがきなどで申込みが可能で、ガイド付きの参観が行われています。', 1, false),
(5, 18, '桂離宮の「新御殿（しんごてん）」が完成した時期として正しいのはどれか。', '16世紀末（安土桃山時代）', '17世紀前半（江戸初期）', '17世紀後半（江戸中期）', '18世紀初期', 2, '桂離宮は古書院→中書院→新御殿の順に段階的に造営されました。新御殿は2代・智忠親王（1619〜1662年）が後水尾上皇の行幸に備えて17世紀中頃（1662年頃）に完成させたものです。', 3, false),
(5, 18, 'ブルーノ・タウトが来日した時期はいつか。', '1923年（関東大震災直後）', '1933年（ナチス台頭後）', '1945年（終戦直後）', '1955年（高度経済成長期）', 1, 'タウトは1933年にナチスが政権を取ったドイツを逃れ、日本に亡命しました。3年3ヵ月滞在し桂離宮・伊勢神宮などを訪問して日本の伝統建築を称賛し、著作「日本美の再発見」などを残しました。', 2, false),
(5, 18, '桂離宮の庭園で「飛び石（とびいし）」が多用されている理由として正しいのはどれか。', '庭を広く見せる遠近法の手法', '茶道の精神に基づいた茶の道（露地）の概念', '歩きやすくするための実用的配置', '装飾的な意匠として配置', 1, '桂離宮の庭園には大量の飛び石が配されており、これは茶道の「露地（ろじ）」の概念に基づいています。茶室へ向かう参道を飛び石で表し、俗界から離れた非日常の心境へと誘う演出です。', 2, false),
(5, 18, '桂離宮の建築様式として最も特徴的なものはどれか。', '権現造（ごんげんづくり）', '数奇屋造（すきやづくり）', '寝殿造（しんでんづくり）', '書院造（しょいんづくり）', 1, '桂離宮の建築は「数奇屋造（すきやづくり）」の粋を極めたものとされています。茶道の精神（わびさび）を建築に取り込んだ様式で、装飾を排した清潔感のある空間が特徴です。', 1, false),
(5, 18, '桂離宮の敷地面積はおよそどれくらいか。', '約1万㎡', '約7万㎡', '約15万㎡', '約30万㎡', 1, '桂離宮の敷地面積は約7万㎡（約2万1千坪）です。庭園・書院・茶屋などが広大な敷地に配置されており、池を中心とした回遊式庭園として設計されています。', 2, false),
(5, 18, '桂離宮の「賞花亭（しょうかてい）」の名前の由来として正しいのはどれか。', '四季の花を賞（め）でる意味', '中国の故事から', '特定の花の名前に由来', '建築した職人への賞賛の意味', 0, '賞花亭（しょうかてい）は庭園の高台に位置する小さな茶屋で、「花を賞でる（めでる）」という名のとおり、庭全体を見渡しながら四季の花を楽しむ場所として設けられました。', 2, false),
(5, 18, '桂離宮における「州浜（すはま）」とはどのような景観要素か。', '池の端に設けた松の林', '池の水際に玉砂利・玉石を敷いた砂浜を模した地形', '庭石を多用した枯山水部分', '苔で覆われた丘', 1, '州浜（すはま）は池の水際に玉砂利や玉石を敷き詰めて海辺の砂浜を模した景観演出で、桂離宮の池庭に多用されています。海の景観を山の庭園に取り込む手法で、日本庭園の伝統的な技法です。', 3, false),
(5, 18, '桂離宮が「日本建築の原点」として国際的に評価される理由として最も適切なのはどれか。', '最大規模の木造建築物だから', '余白・簡素・自然との調和という普遍的な美が認められるから', '最も多くの国宝を有するから', '日本最古の庭園様式を保存しているから', 1, 'ブルーノ・タウトや多くの建築家が桂離宮を高評価する理由は、過剰な装飾を排した余白の美・簡素さ・自然との調和にあります。これらは近代建築の「機能的な美」とも通じる普遍的価値として国際的に認められています。', 2, false),
(5, 18, '「月波楼（げっぱろう）」が桂離宮でどのような役割を持つ建物か。', '茶の湯を行う大型書院', '月見・舟遊びのための小さな茶屋', '宿泊のための寝殿', '儀式のための正殿', 1, '月波楼（げっぱろう）は池のほとりに建つ小さな茶屋で、池に映る月を楽しみながら舟遊びをする際の休憩所として設けられました。シンプルな造りながら桂離宮の月見文化を象徴する建物です。', 2, false),
(5, 18, '桂離宮を管理する機関として正しいのはどれか。', '京都府教育委員会', '文化庁', '宮内庁', '国土交通省', 2, '桂離宮は修学院離宮とともに宮内庁が管理する皇室用財産（離宮）です。参観申込みも宮内庁のウェブサイトから行う必要があります。', 1, false);

